-- One atomic request budget per tenant and connector, shared by every consumer of the same upstream (lib/advanced/request-budget.ts, #192):
-- the per-(tenant, connector) lock row and the reservation rows, with the 0039 tenant-tombstone guards generated by the same pipeline as every tenant table.
-- Numbered 0058 = main's top (0057) + 1 (Quest 2026-11-10: #192 = 0058; renumbered from 0056 when main landed #973's 0056 and #608's 0057, earlier from 0050), so the 1..n no-gap rule holds.
CREATE TABLE adv_budget_lock (tenant_id TEXT NOT NULL, connector TEXT NOT NULL, n BIGINT NOT NULL DEFAULT 0, since BIGINT NOT NULL DEFAULT 0, PRIMARY KEY (tenant_id, connector));

CREATE TABLE adv_requests (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, connector TEXT NOT NULL, at BIGINT NOT NULL, consumer TEXT NOT NULL);

CREATE INDEX adv_requests_window ON adv_requests (tenant_id, connector, at);

CREATE OR REPLACE FUNCTION dazl_guard_tomb_adv_budget_lock() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtext(NEW.tenant_id));
  IF (EXISTS (SELECT 1 FROM tenant_tombstones WHERE deleted_tenant = NEW.tenant_id)) THEN RAISE EXCEPTION 'tenant deleted'; END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS tomb_adv_budget_lock ON adv_budget_lock;
CREATE TRIGGER tomb_adv_budget_lock BEFORE INSERT ON adv_budget_lock FOR EACH ROW EXECUTE FUNCTION dazl_guard_tomb_adv_budget_lock();

CREATE OR REPLACE FUNCTION dazl_guard_tomb_adv_requests() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtext(NEW.tenant_id));
  IF (EXISTS (SELECT 1 FROM tenant_tombstones WHERE deleted_tenant = NEW.tenant_id)) THEN RAISE EXCEPTION 'tenant deleted'; END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS tomb_adv_requests ON adv_requests;
CREATE TRIGGER tomb_adv_requests BEFORE INSERT ON adv_requests FOR EACH ROW EXECUTE FUNCTION dazl_guard_tomb_adv_requests();

CREATE OR REPLACE FUNCTION dazl_guard_tomb_upd_adv_budget_lock() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtext(NEW.tenant_id));
  PERFORM pg_advisory_xact_lock_shared(hashtext(OLD.tenant_id));
  IF (NEW.tenant_id IS DISTINCT FROM OLD.tenant_id AND ((EXISTS (SELECT 1 FROM tenant_tombstones WHERE deleted_tenant = NEW.tenant_id)) OR (EXISTS (SELECT 1 FROM tenant_tombstones WHERE deleted_tenant = OLD.tenant_id)))) THEN RAISE EXCEPTION 'tenant deleted'; END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS tomb_upd_adv_budget_lock ON adv_budget_lock;
CREATE TRIGGER tomb_upd_adv_budget_lock BEFORE UPDATE OF tenant_id ON adv_budget_lock FOR EACH ROW EXECUTE FUNCTION dazl_guard_tomb_upd_adv_budget_lock();

CREATE OR REPLACE FUNCTION dazl_guard_tomb_upd_adv_requests() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtext(NEW.tenant_id));
  PERFORM pg_advisory_xact_lock_shared(hashtext(OLD.tenant_id));
  IF (NEW.tenant_id IS DISTINCT FROM OLD.tenant_id AND ((EXISTS (SELECT 1 FROM tenant_tombstones WHERE deleted_tenant = NEW.tenant_id)) OR (EXISTS (SELECT 1 FROM tenant_tombstones WHERE deleted_tenant = OLD.tenant_id)))) THEN RAISE EXCEPTION 'tenant deleted'; END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS tomb_upd_adv_requests ON adv_requests;
CREATE TRIGGER tomb_upd_adv_requests BEFORE UPDATE OF tenant_id ON adv_requests FOR EACH ROW EXECUTE FUNCTION dazl_guard_tomb_upd_adv_requests();
